def make_verbs_words():
    words = []
    subs = ["verbs_movement", "verbs_communication", "verbs_daily", "verbs_mind", "verbs_change"]
    for i, w in enumerate(verbs_data):
        sub = subs[i // 50]
        words.append((w[0], w[1], w[2], f"[{w[0].lower()}]", w[3], w[4], w[5], w[6], "verbs", sub, w[7]))
    return words

VERBS_WORDS = make_verbs_words()
